mapper.select:

select 
	unSubmitNum,
	total,
	(case 

	    when total=0 THEN 0 

		else ROUND((1-((CAST (unSubmitNum AS DOUBLE))/total))*100,2) end)as rate,
	pageType
	from(

		select
			count(temp.SEND_STATUS) as total,
			nvl(sum(temp.lateNums),0) as unSubmitNum,
			'11' as pageType
			from(
				select
					case when ces.SEND_STATUS != #{nosubmit}  
						  and ces.CHB_SUBMIT_DEADLINE < ces.SUBMIT_TIME then 1  
						 when ces.SEND_STATUS = #{nosubmit} 
						  and ces.CHB_SUBMIT_DEADLINE < #{sysTime} then 1 
						   else 0 end lateNums,  
					ces.SEND_STATUS,
					ces.ORG_CODE,
					ces.CREATE_DEPT
				 from CHB_INVESTHOLD_INFO_SUB ces
					 where ces.CHB_SUBMIT_DEADLINE >= #{searchDateStart}
					   and ces.CHB_SUBMIT_DEADLINE <= #{searchDateEnd}
				union all

				select
					case when ces.CHB_SUBMIT_DEADLINE < ces.SUBMIT_TIME then 1 
						   else 0 end lateNums,  
					ces.SEND_STATUS,
					ces.ORG_CODE,
					ces.CREATE_DEPT
					from CHB_INVESTHOLD_INFO_SUB_HIS ces
					 where ces.CHB_SUBMIT_DEADLINE >= #{searchDateStart}
						and ces.CHB_SUBMIT_DEADLINE <= #{searchDateEnd}  
			)temp



					temp.SEND_STATUS != #{manualSub}



					#{item,jdbcType=VARCHAR}



		union all


		select
			count(temp.SUBMIT_STATUS) as total,
			nvl(sum(temp.lateNums),0) as unSubmitNum,
			'12' as pageType
			from(
				select
					case when ces.Submit_Status != #{nosubmit}  
						  and ces.CHB_SUBMIT_DEADLINE < ces.SUBMIT_TIME then 1 
						 when ces.Submit_Status = #{nosubmit} 
						  and ces.CHB_SUBMIT_DEADLINE < #{sysTime} then 1 
						   else 0 end lateNums,  
					ces.SUBMIT_STATUS,
					ces.CREATE_DEPT
				 from CHB_EQU_SUB ces
					 where ces.CHB_SUBMIT_DEADLINE >= #{searchDateStart}
					   and ces.CHB_SUBMIT_DEADLINE <= #{searchDateEnd}
				union all

				select
					case when ces.CHB_SUBMIT_DEADLINE < ces.SUBMIT_TIME then 1 
						   else 0 end lateNums, 
					ces.SUBMIT_STATUS,
					ces.CREATE_DEPT
					from CHB_EQU_SUB_HIS ces
					 where ces.CHB_SUBMIT_DEADLINE >= #{searchDateStart}
						and ces.CHB_SUBMIT_DEADLINE <= #{searchDateEnd} 
			)temp



				 temp.SUBMIT_STATUS != #{manualSub}



					#{item,jdbcType=VARCHAR}



	)
